using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using SkibidiVpn.WinUI.Models;using SkibidiVpn.WinUI.Services;
namespace SkibidiVpn.WinUI.Views;
public sealed partial class SourcesPage:Page{private BackendClient? _backend;public SourcesPage(){InitializeComponent();}protected override void OnNavigatedTo(Microsoft.UI.Xaml.Navigation.NavigationEventArgs e){base.OnNavigatedTo(e);_backend=e.Parameter as BackendClient;_ = Refresh();}private async Task Refresh(){try{var data=await _backend!.GetSourcesAsync();SourcesList.ItemsSource=data.Sources.Select(s=>new SourceRow(s.Name,s.Type,s.Url,s.Enabled)).ToArray();SummaryText.Text=$"Всего: {data.Sources.Length} · включено: {data.Sources.Count(x=>x.Enabled)}";}catch(Exception ex){SummaryText.Text="Ошибка: "+ex.Message;}}private async void Refresh_Click(object s,RoutedEventArgs e)=>await Refresh();public sealed record SourceRow(string Name,string Type,string Url,bool Enabled){public string StateLabel=>Enabled?"Включён":"Отключён";}}
